function unique(arr) {
  const seen = new Set();
  const out = [];
  for (const item of arr) {
    if (!seen.has(item)) {
      seen.add(item);
      out.push(item);
    }
  }
  return out;
}

console.log(unique([3, 1, 3, 2, 1])); // [3, 1, 2]

function minBy(arr, keyFn) {
  return arr.reduce((best, item) => (keyFn(item) < keyFn(best) ? item : best));
}
function maxBy(arr, keyFn) {
  return arr.reduce((best, item) => (keyFn(item) > keyFn(best) ? item : best));
}

