function pick(obj, keys) {
  const out = {};
  for (const key of keys) {
    if (key in obj) out[key] = obj[key];
  }
  return out;
}
function omit(obj, keys) {
  const skip = new Set(keys);
  const out = {};
  for (const [key, value] of Object.entries(obj)) {
    if (!skip.has(key)) out[key] = value;
  }
  return out;
}

