function sortByMulti(arr, keys) {
  return [...arr].sort((a, b) => {
    for (const { key, dir = 1 } of keys) {
      if (a[key] < b[key]) return -1 * dir;
      if (a[key] > b[key]) return 1 * dir;
    }
    return 0;
  });
}

